// Package gamedata loads the static game data in data/: monster kinds,
// per-level monster stats, skills and the EXP table. data/monsters.json,
// data/skills.json and data/exp.json are generated by monster_stats.py,
// skill_stats.py and exp_table.py in docs/balance and are never edited by
// hand.
package gamedata

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"demonslayer2d/internal/combat"
	"demonslayer2d/internal/mapdata"
)

// Kind is a monster kind. Speed is a factor of the configured move speed.
type Kind struct {
	ID          string  `json:"id"`
	Name        string  `json:"name"`
	AttackRange float64 `json:"attack_range"`
	AttackSec   float64 `json:"attack_sec"`
	Speed       float64 `json:"speed"`
	// DetectRange is how far a monster notices players to shoot at.
	DetectRange float64 `json:"detect_range"`
	// ChaseRange is how far a chase may run from where it began.
	ChaseRange float64 `json:"chase_range"`
	// ShootSec is the gap between ranged shots; ShootWindupSec delays the first.
	ShootSec       float64 `json:"shoot_sec"`
	ShootWindupSec float64 `json:"shoot_windup_sec"`
	// RegionMargin is how many tiles outside its region a target may be
	// before the monster gives up the chase.
	RegionMargin float64 `json:"region_margin"`
	// ChaseSpeed is the chase and attack move speed, a factor of the
	// configured move speed; above 1 so a retreating player cannot kite.
	ChaseSpeed float64 `json:"chase_speed"`
	// SafeWaitSec is how long a chasing monster waits at the edge for a
	// target that stays in a safe zone.
	SafeWaitSec float64 `json:"safe_wait_sec"`
	// MarginGraceSec is how long a target may stay beyond the region margin
	// before the monster gives up the chase.
	MarginGraceSec float64 `json:"margin_grace_sec"`
	// GrudgeSec is how long a monster remembers a player who hit it, and
	// chases them on sight instead of shooting.
	GrudgeSec  float64 `json:"grudge_sec"`
	RespawnSec float64 `json:"respawn_sec"`
	// MeleeWindupMS is the time from a melee swing starting to its impact;
	// ShotSpeed is how fast a ranged shot flies, in tiles per second.
	MeleeWindupMS int     `json:"melee_windup_ms"`
	ShotSpeed     float64 `json:"shot_speed"`
	// Rank is the monster's rank (normal, elite or boss); it picks the
	// drop table and the reward multipliers.
	Rank string `json:"rank"`
}

// Level holds the monster stats of one level. Defense serves as both
// physical and magic defense.
type Level struct {
	Level   int `json:"level"`
	HP      int `json:"hp"`
	Attack  int `json:"attack"`
	Defense int `json:"defense"`
	// Exp is the total base EXP the monster pays, shared by damage dealt.
	Exp int64 `json:"exp"`
}

// Data is the parsed monsters.json.
type Data struct {
	Kinds  map[string]Kind
	Levels map[int]Level
	// Skills is skills.json by id. ClassSkills lists each class's five
	// skills ordered by slot 1-4, then the passive (slot 0) last.
	Skills      map[string]Skill
	ClassSkills map[string][]Skill
	// Exp is the EXP needed to leave each level, index 0 = level 1.
	Exp combat.ExpTable
}

type file struct {
	Kinds  []Kind  `json:"kinds"`
	Levels []Level `json:"levels"`
}

// Parse decodes and validates monsters.json.
func Parse(b []byte) (*Data, error) {
	var f file
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&f); err != nil {
		return nil, fmt.Errorf("gamedata: decode: %w", err)
	}
	d := &Data{Kinds: make(map[string]Kind, len(f.Kinds)), Levels: make(map[int]Level, len(f.Levels))}
	for _, k := range f.Kinds {
		if k.ID == "" {
			return nil, errors.New("gamedata: kind with empty id")
		}
		if _, dup := d.Kinds[k.ID]; dup {
			return nil, fmt.Errorf("gamedata: duplicate kind %q", k.ID)
		}
		for name, v := range map[string]float64{
			"attack_range": k.AttackRange, "attack_sec": k.AttackSec, "speed": k.Speed,
			"detect_range": k.DetectRange, "chase_range": k.ChaseRange, "shoot_sec": k.ShootSec,
			"shoot_windup_sec": k.ShootWindupSec, "chase_speed": k.ChaseSpeed, "safe_wait_sec": k.SafeWaitSec,
			"margin_grace_sec": k.MarginGraceSec, "grudge_sec": k.GrudgeSec,
			"respawn_sec": k.RespawnSec, "melee_windup_ms": float64(k.MeleeWindupMS), "shot_speed": k.ShotSpeed,
		} {
			// The negated comparison also rejects NaN.
			if !(v > 0) {
				return nil, fmt.Errorf("gamedata: kind %q: %s must be positive", k.ID, name)
			}
		}
		if !(k.RegionMargin >= 0) {
			return nil, fmt.Errorf("gamedata: kind %q: region_margin must not be negative", k.ID)
		}
		d.Kinds[k.ID] = k
	}
	for _, l := range f.Levels {
		if _, dup := d.Levels[l.Level]; dup {
			return nil, fmt.Errorf("gamedata: duplicate level %d", l.Level)
		}
		if l.Level <= 0 || l.HP <= 0 || l.Attack <= 0 || l.Defense <= 0 || l.Exp <= 0 {
			return nil, fmt.Errorf("gamedata: level %d: every number must be positive", l.Level)
		}
		d.Levels[l.Level] = l
	}
	return d, nil
}

// Load reads dir/monsters.json, skills.json and exp.json.
func Load(dir string) (*Data, error) {
	read := func(name string) ([]byte, error) {
		b, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			return nil, fmt.Errorf("gamedata: %w", err)
		}
		return b, nil
	}
	b, err := read("monsters.json")
	if err != nil {
		return nil, err
	}
	d, err := Parse(b)
	if err != nil {
		return nil, err
	}
	if b, err = read("skills.json"); err != nil {
		return nil, err
	}
	if d.Skills, err = ParseSkills(b); err != nil {
		return nil, err
	}
	d.ClassSkills = classSkills(d.Skills)
	if b, err = read("exp.json"); err != nil {
		return nil, err
	}
	if d.Exp, err = ParseExp(b); err != nil {
		return nil, err
	}
	return d, nil
}

// Validate checks every region of every map: its monster kind exists
// and every level in min_level..max_level has stats.
func (d *Data) Validate(maps map[string]*mapdata.Map) error {
	for id, m := range maps {
		for _, r := range m.Regions {
			if _, ok := d.Kinds[r.Monster]; !ok {
				return fmt.Errorf("gamedata: map %q region %q: unknown monster %q", id, r.ID, r.Monster)
			}
			for l := r.MinLevel; l <= r.MaxLevel; l++ {
				if _, ok := d.Levels[l]; !ok {
					return fmt.Errorf("gamedata: map %q region %q: no stats for level %d", id, r.ID, l)
				}
			}
		}
	}
	return nil
}
